package cn.xiaoyanjiu.ff14chat;
import android.app.AlertDialog;import android.content.Context;import android.graphics.Typeface;import android.graphics.drawable.*;import android.content.res.ColorStateList;import android.view.*;import android.widget.*;import org.json.JSONObject;
/** Native dialogs share the WebView's FF14 palette and button states. */
final class GameDialogStyle {
 static boolean enabled(Context c){try{return new JSONObject(c.getSharedPreferences("appearance",0).getString("settings","{}")).optString("theme").equals("game");}catch(Exception e){return false;}}
 static AlertDialog.Builder builder(Context c){return new AlertDialog.Builder(c,enabled(c)?android.R.style.Theme_Material_Dialog_Alert:0){@Override public AlertDialog show(){AlertDialog d=super.show();apply(c,d);if(d.getWindow()!=null)d.getWindow().getDecorView().post(()->apply(c,d));return d;}};}
 static GradientDrawable surface(Context c,int[] colors,int stroke,float radius){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,colors);float density=c.getResources().getDisplayMetrics().density;d.setCornerRadius(radius*density);d.setStroke(Math.max(1,Math.round(density)),stroke);return d;}
 static void apply(Context c,AlertDialog d){if(!enabled(c)||d.getWindow()==null)return;d.getWindow().setBackgroundDrawable(surface(c,new int[]{0xff4a494a,0xff313031,0xff313031},0xffb7a277,8));d.getWindow().getDecorView().setElevation(9*c.getResources().getDisplayMetrics().density);paint(c,d.getWindow().getDecorView());for(int id:new int[]{AlertDialog.BUTTON_POSITIVE,AlertDialog.BUTTON_NEGATIVE,AlertDialog.BUTTON_NEUTRAL}){Button b=d.getButton(id);if(b==null)continue;boolean primary=id==AlertDialog.BUTTON_POSITIVE;StateListDrawable states=new StateListDrawable();states.addState(new int[]{android.R.attr.state_pressed},surface(c,primary?new int[]{0xff8f7139,0xffbb974d}:new int[]{0xff292929,0xff454545},primary?0xffd4bb7e:0xff252525,30));states.addState(new int[]{},surface(c,primary?new int[]{0xfffff0b0,0xffbf9d55,0xff92733a,0xffbb9850}:new int[]{0xff666666,0xff464646,0xff353535,0xff414141},primary?0xffd4bb7e:0xff252525,30));b.setBackground(states);b.setTextColor(new ColorStateList(new int[][]{new int[]{-android.R.attr.state_enabled},new int[]{}},new int[]{0xff858581,primary?0xfffffbe9:0xffdeddd8}));b.setTextSize(13);b.setAllCaps(false);int height=Math.round(34*c.getResources().getDisplayMetrics().density);b.setMinHeight(0);b.setMinimumHeight(0);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(Math.round(14*c.getResources().getDisplayMetrics().density),0,Math.round(14*c.getResources().getDisplayMetrics().density),0);android.view.ViewGroup.LayoutParams layout=b.getLayoutParams();layout.height=height;b.setLayoutParams(layout);b.setShadowLayer(1,0,1,0xff171717);}}
 static void paint(Context c,View v){if(v instanceof TextView){TextView t=(TextView)v;t.setTextColor(0xffdeddd8);t.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));if(!(t instanceof Button))t.setTextSize(14);if(t instanceof EditText){t.setHintTextColor(0xff9e9d9b);t.setBackground(surface(c,new int[]{0xff4b4a4b,0xff454445},0xff242424,4));int pad=(int)(8*c.getResources().getDisplayMetrics().density);t.setPadding(pad,pad,pad,pad);}}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)paint(c,g.getChildAt(i));}}
}
